  ('麻黄'::text, 'Ephedrae Herba'::text, '麻黄科植物草麻黄、中麻黄或木贼麻黄的干燥草质茎'::text, array['辛', '微苦']::text[], '温'::text, array['肺', '膀胱']::text[], '发汗散寒，宣肺平喘，利水消肿'::text, '生用；蜜炙后发汗力缓，多用于平喘'::text, '山西、内蒙古、河北'::text, '茎粗、色淡绿或黄绿、髓部红棕色、味苦涩者佳'::text, 'none'::text, '表虚自汗、阴虚盗汗及肺肾虚喘者慎用；含麻黄碱，高血压、失眠者慎用'::text, '置通风干燥处，防潮'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('桂枝'::text, 'Cinnamomi Ramulus'::text, '樟科植物肉桂的干燥嫩枝'::text, array['辛', '甘']::text[], '温'::text, array['心', '肺', '膀胱']::text[], '发汗解肌，温通经脉，助阳化气，平冲降气'::text, '生用'::text, '广西、广东'::text, '枝条细嫩均匀、色棕红、香气浓者佳'::text, 'none'::text, '孕妇慎用；温热病、阴虚阳盛、血热妄行者忌用'::text, '置阴凉干燥处'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('紫苏叶'::text, 'Perillae Folium'::text, '唇形科植物紫苏的干燥叶（或带嫩枝）'::text, array['辛']::text[], '温'::text, array['肺', '脾']::text[], '解表散寒，行气和胃'::text, '生用'::text, '江苏、浙江、河北'::text, '叶完整、色紫、香气浓者佳'::text, 'none'::text, '温病及气弱表虚者慎用'::text, '置阴凉干燥处'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('生姜'::text, 'Zingiberis Rhizoma Recens'::text, '姜科植物姜的新鲜根茎'::text, array['辛']::text[], '微温'::text, array['肺', '脾', '胃']::text[], '解表散寒，温中止呕，化痰止咳，解鱼蟹毒'::text, '鲜用，切片或捣汁'::text, '四川、贵州、山东'::text, '块大、丰满、质嫩者佳'::text, 'none'::text, '阴虚内热者慎用'::text, '置阴凉潮湿处，或埋入湿沙内，防冻'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('荆芥'::text, 'Schizonepetae Herba'::text, '唇形科植物荆芥的干燥地上部分'::text, array['辛']::text[], '微温'::text, array['肺', '肝']::text[], '解表散风，透疹，消疮'::text, '生用；炒炭（荆芥炭）用于止血'::text, '江苏、浙江、河北'::text, '色淡黄绿、穗长而密、香气浓者佳'::text, 'none'::text, '表虚自汗者慎用'::text, '置阴凉干燥处'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('防风'::text, 'Saposhnikoviae Radix'::text, '伞形科植物防风的干燥根'::text, array['辛', '甘']::text[], '微温'::text, array['膀胱', '肝', '脾']::text[], '祛风解表，胜湿止痛，止痉'::text, '生用'::text, '黑龙江、吉林、内蒙古（关防风）'::text, '条粗壮、断面皮部浅棕色、木部浅黄色者佳'::text, 'none'::text, '阴血亏虚、热病动风者不宜'::text, '置阴凉干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('白芷'::text, 'Angelicae Dahuricae Radix'::text, '伞形科植物白芷或杭白芷的干燥根'::text, array['辛']::text[], '温'::text, array['胃', '大肠', '肺']::text[], '解表散寒，祛风止痛，宣通鼻窍，燥湿止带，消肿排脓'::text, '生用'::text, '四川（川白芷）、浙江（杭白芷）、河南（禹白芷）'::text, '条粗壮、质硬、粉性足、香气浓者佳'::text, 'none'::text, '阴虚血热者忌用'::text, '置阴凉干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('薄荷'::text, 'Menthae Haplocalycis Herba'::text, '唇形科植物薄荷的干燥地上部分'::text, array['辛']::text[], '凉'::text, array['肺', '肝']::text[], '疏散风热，清利头目，利咽，透疹，疏肝行气'::text, '生用；入汤剂宜后下'::text, '江苏（苏薄荷）'::text, '叶多、色深绿、香气浓者佳'::text, 'none'::text, '体虚多汗者不宜'::text, '置阴凉干燥处'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('桑叶'::text, 'Mori Folium'::text, '桑科植物桑的干燥叶'::text, array['甘', '苦']::text[], '寒'::text, array['肺', '肝']::text[], '疏散风热，清肺润燥，清肝明目'::text, '生用或蜜炙（润肺止咳）'::text, '全国大部分地区，以南方育蚕区为多'::text, '叶片完整、大而厚、色黄绿者佳'::text, 'none'::text, null::text, '置干燥处'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('菊花'::text, 'Chrysanthemi Flos'::text, '菊科植物菊的干燥头状花序'::text, array['甘', '苦']::text[], '微寒'::text, array['肺', '肝']::text[], '散风清热，平肝明目，清热解毒'::text, '生用'::text, '浙江（杭菊）、安徽（亳菊、滁菊、贡菊）、河南（怀菊）'::text, '花朵完整、颜色鲜艳、香气浓郁者佳'::text, 'none'::text, '脾胃虚寒者慎用'::text, '置阴凉干燥处，密闭保存，防霉，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('葛根'::text, 'Puerariae Lobatae Radix'::text, '豆科植物野葛的干燥根'::text, array['甘', '辛']::text[], '凉'::text, array['脾', '胃', '肺']::text[], '解肌退热，生津止渴，透疹，升阳止泻，通经活络，解酒毒'::text, '生用；煨用偏于止泻'::text, '湖南、河南、广东、浙江'::text, '块大、质坚实、色白、粉性足、纤维少者佳'::text, 'none'::text, null::text, '置通风干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('柴胡'::text, 'Bupleuri Radix'::text, '伞形科植物柴胡（北柴胡）或狭叶柴胡（南柴胡）的干燥根'::text, array['辛', '苦']::text[], '微寒'::text, array['肝', '胆', '肺']::text[], '疏散退热，疏肝解郁，升举阳气'::text, '生用或醋炙（醋柴胡偏于疏肝）'::text, '河北、河南、辽宁（北柴胡）'::text, '条粗长、须根少者佳'::text, 'none'::text, '肝阳上亢、肝风内动、阴虚火旺及气机上逆者慎用'::text, '置通风干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('升麻'::text, 'Cimicifugae Rhizoma'::text, '毛茛科植物大三叶升麻、兴安升麻或升麻的干燥根茎'::text, array['辛', '微甘']::text[], '微寒'::text, array['肺', '脾', '胃', '大肠']::text[], '发表透疹，清热解毒，升举阳气'::text, '生用或蜜炙'::text, '辽宁、黑龙江、四川'::text, '个大、质坚、外皮黑褐色、断面黄绿色者佳'::text, 'none'::text, '麻疹已透、阴虚火旺、阴虚阳亢者忌用'::text, '置通风干燥处'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('石膏'::text, 'Gypsum Fibrosum'::text, '硫酸盐类矿物石膏族石膏，主含含水硫酸钙'::text, array['甘', '辛']::text[], '大寒'::text, array['肺', '胃']::text[], '清热泻火，除烦止渴；煅石膏外用收湿，生肌，敛疮，止血'::text, '生用打碎，入汤剂先煎；煅用多外用'::text, '湖北应城、安徽'::text, '块大、色白、纵断面纤维状、有绢丝样光泽、无杂石者佳'::text, 'none'::text, '脾胃虚寒及阴虚内热者忌用'::text, '置干燥处'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
