  ('薏苡仁'::text, 'Coicis Semen'::text, '禾本科植物薏米的干燥成熟种仁'::text, array['甘', '淡']::text[], '凉'::text, array['脾', '胃', '肺']::text[], '利水渗湿，健脾止泻，除痹，排脓，解毒散结'::text, '生用或麸炒（偏于健脾止泻）'::text, '福建、河北、辽宁'::text, '粒大、饱满、色白、完整者佳'::text, 'none'::text, '孕妇慎用'::text, '置通风干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
