  ('干姜'::text, 'Zingiberis Rhizoma'::text, '姜科植物姜的干燥根茎'::text, array['辛']::text[], '热'::text, array['脾', '胃', '肾', '心', '肺']::text[], '温中散寒，回阳通脉，温肺化饮'::text, '生用；炮制成炮姜偏于温经止血'::text, '四川（犍为）、贵州'::text, '质坚实、断面色黄白、粉性足、气味浓者佳'::text, 'none'::text, '阴虚内热、血热妄行者忌用；孕妇慎用'::text, '置阴凉干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('肉桂'::text, 'Cinnamomi Cortex'::text, '樟科植物肉桂的干燥树皮'::text, array['辛', '甘']::text[], '大热'::text, array['肾', '脾', '心', '肝']::text[], '补火助阳，引火归元，散寒止痛，温通经脉'::text, '生用；入汤剂宜后下'::text, '广西、广东'::text, '皮细肉厚、断面紫红色、油性大、香气浓、味甜辣、嚼之无渣者佳'::text, 'none'::text, '有出血倾向者及孕妇慎用；不宜与赤石脂同用'::text, '置阴凉干燥处，密闭'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('陈皮'::text, 'Citri Reticulatae Pericarpium'::text, '芸香科植物橘及其栽培变种的干燥成熟果皮'::text, array['苦', '辛']::text[], '温'::text, array['肺', '脾']::text[], '理气健脾，燥湿化痰'::text, '生用'::text, '广东新会（广陈皮）、四川、福建'::text, '片大、色鲜、油润、质软、香气浓、味甜苦辛者佳；陈久者良'::text, 'none'::text, '舌赤少津、内有实热者慎用'::text, '置阴凉干燥处，防霉，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('枳壳'::text, 'Aurantii Fructus'::text, '芸香科植物酸橙及其栽培变种的干燥未成熟果实'::text, array['苦', '辛', '酸']::text[], '微寒'::text, array['脾', '胃']::text[], '理气宽中，行滞消胀'::text, '生用或麸炒'::text, '江西（江枳壳）、四川、湖南'::text, '外皮绿褐色、果肉厚、质坚硬、香气浓者佳'::text, 'none'::text, '孕妇慎用'::text, '置阴凉干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('枳实'::text, 'Aurantii Fructus Immaturus'::text, '芸香科植物酸橙及其栽培变种或甜橙的干燥幼果'::text, array['苦', '辛', '酸']::text[], '微寒'::text, array['脾', '胃']::text[], '破气消积，化痰散痞'::text, '生用或麸炒'::text, '四川、江西、湖南'::text, '外皮黑绿色、肉厚色白、瓤小、体坚实、香气浓者佳'::text, 'none'::text, '孕妇慎用'::text, '置阴凉干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('木香'::text, 'Aucklandiae Radix'::text, '菊科植物木香的干燥根'::text, array['辛', '苦']::text[], '温'::text, array['脾', '胃', '大肠', '三焦', '胆']::text[], '行气止痛，健脾消食'::text, '生用或煨用（偏于止泻）'::text, '云南（云木香）'::text, '质坚实、香气浓、油性大者佳'::text, 'none'::text, '阴虚津亏、火旺者慎用'::text, '置干燥处，防潮'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('香附'::text, 'Cyperi Rhizoma'::text, '莎草科植物莎草的干燥根茎'::text, array['辛', '微苦', '微甘']::text[], '平'::text, array['肝', '脾', '三焦']::text[], '疏肝解郁，理气宽中，调经止痛'::text, '生用或醋炙'::text, '山东、浙江、湖南'::text, '个大、质坚实、色棕褐、香气浓者佳'::text, 'none'::text, '气虚无滞、阴虚血热者慎用'::text, '置阴凉干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('佛手'::text, 'Citri Sarcodactylis Fructus'::text, '芸香科植物佛手的干燥果实'::text, array['辛', '苦', '酸']::text[], '温'::text, array['肝', '脾', '胃', '肺']::text[], '疏肝理气，和胃止痛，燥湿化痰'::text, '生用'::text, '广东（广佛手）、四川（川佛手）、浙江（金佛手）'::text, '片大、绿皮白肉、香气浓者佳'::text, 'none'::text, '阴虚有火、无气滞者慎用'::text, '置阴凉干燥处，防霉，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('山楂'::text, 'Crataegi Fructus'::text, '蔷薇科植物山里红或山楂的干燥成熟果实'::text, array['酸', '甘']::text[], '微温'::text, array['脾', '胃', '肝']::text[], '消食健胃，行气散瘀，化浊降脂'::text, '生用、炒用或炒焦'::text, '山东、河北、河南'::text, '片大、皮红、肉厚者佳'::text, 'none'::text, '脾胃虚弱而无积滞者、胃酸分泌过多者慎用'::text, '置通风干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('神曲'::text, 'Massa Medicata Fermentata'::text, '面粉和杏仁泥、赤小豆、青蒿、苍耳、辣蓼等混合后经发酵而成的加工品'::text, array['甘', '辛']::text[], '温'::text, array['脾', '胃']::text[], '消食和胃'::text, '生用或炒焦（焦神曲）'::text, '全国各地均有生产'::text, '陈久、无虫蛀、无霉变者佳'::text, 'none'::text, null::text, '置阴凉干燥处，防潮，防蛀'::text, '中药学教材'::text, '药典未收载，依据《中药学》教材和地方炮制规范；各地配方不完全一样'::text, 'draft'::text, null::text, null::date),
  ('麦芽'::text, 'Hordei Fructus Germinatus'::text, '禾本科植物大麦的成熟果实经发芽干燥的炮制加工品'::text, array['甘']::text[], '平'::text, array['脾', '胃']::text[], '行气消食，健脾开胃，回乳消胀'::text, '生用、炒黄（炒麦芽）或炒焦（焦麦芽）'::text, '全国各地'::text, '色黄、粒大、饱满、芽完整者佳'::text, 'none'::text, '哺乳期妇女不宜（回乳）'::text, '置通风干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('鸡内金'::text, 'Galli Gigerii Endothelium Corneum'::text, '雉科动物家鸡的干燥沙囊内壁'::text, array['甘']::text[], '平'::text, array['脾', '胃', '小肠', '膀胱']::text[], '健胃消食，涩精止遗，通淋化石'::text, '生用、炒用或醋炙'::text, '全国各地'::text, '个大、色黄、完整、少破碎者佳'::text, 'none'::text, '脾虚无积滞者慎用'::text, '置干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('川芎'::text, 'Chuanxiong Rhizoma'::text, '伞形科植物川芎的干燥根茎'::text, array['辛']::text[], '温'::text, array['肝', '胆', '心包']::text[], '活血行气，祛风止痛'::text, '生用或酒炙'::text, '四川都江堰、彭州'::text, '个大、质坚实、断面黄白色、油性大、香气浓者佳'::text, 'none'::text, '阴虚火旺、多汗、热盛及无瘀之出血证慎用；孕妇慎用'::text, '置阴凉干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('丹参'::text, 'Salviae Miltiorrhizae Radix et Rhizoma'::text, '唇形科植物丹参的干燥根和根茎'::text, array['苦']::text[], '微寒'::text, array['心', '肝']::text[], '活血祛瘀，通经止痛，清心除烦，凉血消痈'::text, '生用或酒炙'::text, '四川（川丹参）、山东、河南'::text, '条粗壮、色紫红者佳'::text, 'none'::text, '不宜与藜芦同用；孕妇慎用'::text, '置干燥处'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('桃仁'::text, 'Persicae Semen'::text, '蔷薇科植物桃或山桃的干燥成熟种子'::text, array['苦', '甘']::text[], '平'::text, array['心', '肝', '大肠']::text[], '活血祛瘀，润肠通便，止咳平喘'::text, '生用、燀用或炒用，用时捣碎'::text, '四川、陕西、河北'::text, '颗粒饱满、均匀、完整者佳'::text, 'minor'::text, '孕妇慎用；便溏者慎用；含苦杏仁苷，不宜过量'::text, '置阴凉干燥处，防蛀'::text, '中药学教材'::text, '《中药学》教材记「有小毒」；药典是否标注小毒没有核实。这里按更谨慎的写'::text, 'draft'::text, null::text, null::date),
  ('红花'::text, 'Carthami Flos'::text, '菊科植物红花的干燥花'::text, array['辛']::text[], '温'::text, array['心', '肝']::text[], '活血通经，散瘀止痛'::text, '生用'::text, '新疆、河南、四川'::text, '花冠长、色红黄、鲜艳、质柔软者佳'::text, 'none'::text, '孕妇慎用；有出血倾向者不宜多用'::text, '置阴凉干燥处，防潮，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('牛膝'::text, 'Achyranthis Bidentatae Radix'::text, '苋科植物牛膝的干燥根（怀牛膝）'::text, array['苦', '甘', '酸']::text[], '平'::text, array['肝', '肾']::text[], '逐瘀通经，补肝肾，强筋骨，利尿通淋，引血下行'::text, '生用、酒炙或盐炙'::text, '河南焦作一带（怀牛膝）'::text, '根长、肉肥、皮细、黄白色者佳'::text, 'none'::text, '孕妇慎用'::text, '置阴凉干燥处，防潮'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('川牛膝'::text, 'Cyathulae Radix'::text, '苋科植物川牛膝的干燥根'::text, array['甘', '微苦']::text[], '平'::text, array['肝', '肾']::text[], '逐瘀通经，通利关节，利尿通淋'::text, '生用或酒炙'::text, '四川天全、雅安'::text, '条粗壮、质柔韧、分枝少、断面浅黄色者佳'::text, 'none'::text, '孕妇慎用'::text, '置阴凉干燥处，防潮'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('益母草'::text, 'Leonuri Herba'::text, '唇形科植物益母草的新鲜或干燥地上部分'::text, array['苦', '辛']::text[], '微寒'::text, array['肝', '心包', '膀胱']::text[], '活血调经，利尿消肿，清热解毒'::text, '生用'::text, '全国大部分地区'::text, '质嫩、叶多、色灰绿者佳'::text, 'none'::text, '孕妇慎用'::text, '置干燥处'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('三七'::text, 'Notoginseng Radix et Rhizoma'::text, '五加科植物三七的干燥根和根茎'::text, array['甘', '微苦']::text[], '温'::text, array['肝', '胃']::text[], '散瘀止血，消肿定痛'::text, '生用，多研粉'::text, '云南文山'::text, '个大、体重、质坚、表面光滑、断面灰绿色或黄绿色者佳'::text, 'none'::text, '孕妇慎用'::text, '置阴凉干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('半夏'::text, 'Pinelliae Rhizoma'::text, '天南星科植物半夏的干燥块茎（生半夏）'::text, array['辛']::text[], '温'::text, array['脾', '胃', '肺']::text[], '燥湿化痰，降逆止呕，消痞散结'::text, '生品一般不内服；内服用炮制品（法半夏、姜半夏、清半夏）'::text, '四川、湖北、甘肃'::text, '个大、皮净、色白、质坚实、粉性足者佳'::text, 'toxic'::text, '生品内服宜慎；孕妇慎用；不宜与川乌、制川乌、草乌、制草乌、附子同用'::text, '置通风干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('桔梗'::text, 'Platycodonis Radix'::text, '桔梗科植物桔梗的干燥根'::text, array['苦', '辛']::text[], '平'::text, array['肺']::text[], '宣肺，利咽，祛痰，排脓'::text, '生用'::text, '安徽、山东、江苏、内蒙古'::text, '条肥大、色白、质坚实、味苦者佳'::text, 'none'::text, '阴虚久咳及咳血者不宜；用量过大易致恶心呕吐'::text, '置通风干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('川贝母'::text, 'Fritillariae Cirrhosae Bulbus'::text, '百合科植物川贝母、暗紫贝母、甘肃贝母、梭砂贝母、太白贝母或瓦布贝母的干燥鳞茎'::text, array['苦', '甘']::text[], '微寒'::text, array['肺', '心']::text[], '清热润肺，化痰止咳，散结消痈'::text, '生用，多研粉'::text, '四川、青海、西藏、甘肃'::text, '质坚实、粉性足、色白者佳（「怀中抱月」的松贝为上）'::text, 'none'::text, '不宜与川乌、制川乌、草乌、制草乌、附子同用'::text, '置通风干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('浙贝母'::text, 'Fritillariae Thunbergii Bulbus'::text, '百合科植物浙贝母的干燥鳞茎'::text, array['苦']::text[], '寒'::text, array['肺', '心']::text[], '清热化痰止咳，解毒散结消痈'::text, '生用'::text, '浙江宁波（象贝）'::text, '鳞叶肥厚、质坚实、粉性足、断面白色者佳'::text, 'none'::text, '不宜与川乌、制川乌、草乌、制草乌、附子同用'::text, '置干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('苦杏仁'::text, 'Armeniacae Semen Amarum'::text, '蔷薇科植物山杏、西伯利亚杏、东北杏或杏的干燥成熟种子'::text, array['苦']::text[], '微温'::text, array['肺', '大肠']::text[], '降气止咳平喘，润肠通便'::text, '生用、燀用或炒用，用时捣碎'::text, '内蒙古、吉林、辽宁、河北'::text, '颗粒饱满、完整、味苦者佳'::text, 'minor'::text, '内服不宜过量，以免中毒；婴儿慎用；阴虚咳喘及大便溏泄者忌用'::text, '置阴凉干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('酸枣仁'::text, 'Ziziphi Spinosae Semen'::text, '鼠李科植物酸枣的干燥成熟种子'::text, array['甘', '酸']::text[], '平'::text, array['肝', '胆', '心']::text[], '养心补肝，宁心安神，敛汗，生津'::text, '生用或炒用，用时捣碎'::text, '河北邢台、河南、陕西'::text, '粒大、饱满、外皮紫红色、无核壳者佳'::text, 'none'::text, '有实邪郁火及滑泄者慎用'::text, '置阴凉干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('远志'::text, 'Polygalae Radix'::text, '远志科植物远志或卵叶远志的干燥根'::text, array['苦', '辛']::text[], '温'::text, array['心', '肾', '肺']::text[], '安神益智，交通心肾，祛痰，消肿'::text, '多用甘草汤制（制远志）'::text, '山西、陕西、河北'::text, '筒粗、肉厚、去净木心者佳'::text, 'none'::text, '胃溃疡、胃炎患者慎用'::text, '置通风干燥处'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('龙骨'::text, 'Os Draconis'::text, '古代哺乳动物如三趾马、犀类、鹿类、牛类、象类等骨骼的化石'::text, array['甘', '涩']::text[], '平'::text, array['心', '肝', '肾']::text[], '镇惊安神，平肝潜阳，收敛固涩'::text, '生用打碎，入汤剂先煎；煅用偏于收敛固涩'::text, '山西、内蒙古、河南'::text, '质硬、色白、吸湿性强者佳'::text, 'none'::text, '湿热积滞者不宜'::text, '置干燥处，防潮'::text, '中药学教材'::text, '药典未收载，依据《中药学》教材和地方标准'::text, 'draft'::text, null::text, null::date),
  ('牡蛎'::text, 'Ostreae Concha'::text, '牡蛎科动物长牡蛎、大连湾牡蛎或近江牡蛎的贝壳'::text, array['咸']::text[], '微寒'::text, array['肝', '胆', '肾']::text[], '重镇安神，潜阳补阴，软坚散结；煅牡蛎收敛固涩，制酸止痛'::text, '生用打碎，入汤剂先煎；或煅用'::text, '沿海各地'::text, '个大、整齐、内面光洁、色白者佳'::text, 'none'::text, '虚寒者不宜多服'::text, '置干燥处'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('天麻'::text, 'Gastrodiae Rhizoma'::text, '兰科植物天麻的干燥块茎'::text, array['甘']::text[], '平'::text, array['肝']::text[], '息风止痉，平抑肝阳，祛风通络'::text, '生用'::text, '贵州、云南（昭通）、四川、陕西'::text, '个大、质坚实、色黄白、断面半透明、无空心者佳（冬麻优于春麻）'::text, 'none'::text, null::text, '置通风干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('钩藤'::text, 'Uncariae Ramulus cum Uncis'::text, '茜草科植物钩藤、大叶钩藤、毛钩藤、华钩藤或无柄果钩藤的干燥带钩茎枝'::text, array['甘']::text[], '凉'::text, array['肝', '心包']::text[], '息风定惊，清热平肝'::text, '生用；入汤剂宜后下'::text, '广西、江西、湖南'::text, '双钩、茎细、钩结实、光滑、色紫红者佳'::text, 'none'::text, null::text, '置干燥处'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('人参'::text, 'Ginseng Radix et Rhizoma'::text, '五加科植物人参的干燥根和根茎'::text, array['甘', '微苦']::text[], '微温'::text, array['脾', '肺', '心', '肾']::text[], '大补元气，复脉固脱，补脾益肺，生津养血，安神益智'::text, '生晒参或蒸制成红参；入汤剂宜另煎兑服'::text, '吉林、辽宁、黑龙江'::text, '支大、浆足、纹细、芦长、碗密、有珍珠点者佳'::text, 'none'::text, '不宜与藜芦、五灵脂同用；实证、热证而正气不虚者忌用'::text, '置阴凉干燥处，密闭保存，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('西洋参'::text, 'Panacis Quinquefolii Radix'::text, '五加科植物西洋参的干燥根'::text, array['甘', '微苦']::text[], '凉'::text, array['心', '肺', '肾']::text[], '补气养阴，清热生津'::text, '生用，切片或研粉；入汤剂宜另煎兑服'::text, '原产美国、加拿大；中国吉林、山东、北京有栽培'::text, '条匀、质硬、体轻、表面横纹紧密、气清香、味浓者佳'::text, 'none'::text, '不宜与藜芦同用；中阳衰微、胃有寒湿者忌用'::text, '置阴凉干燥处，密闭，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('党参'::text, 'Codonopsis Radix'::text, '桔梗科植物党参、素花党参或川党参的干燥根'::text, array['甘']::text[], '平'::text, array['脾', '肺']::text[], '健脾益肺，养血生津'::text, '生用或米炒'::text, '山西（潞党参）、甘肃（纹党、白条党）'::text, '条粗壮、质柔润、外皮细、横纹多、味甜、嚼之无渣者佳'::text, 'none'::text, '不宜与藜芦同用'::text, '置通风干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('太子参'::text, 'Pseudostellariae Radix'::text, '石竹科植物孩儿参的干燥块根'::text, array['甘', '微苦']::text[], '平'::text, array['脾', '肺']::text[], '益气健脾，生津润肺'::text, '生用'::text, '福建柘荣、贵州、江苏'::text, '条粗、色黄白、无须根者佳'::text, 'none'::text, '邪实而正气不虚者慎用'::text, '置通风干燥处，防潮，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('黄芪'::text, 'Astragali Radix'::text, '豆科植物蒙古黄芪或膜荚黄芪的干燥根'::text, array['甘']::text[], '微温'::text, array['肺', '脾']::text[], '补气升阳，固表止汗，利水消肿，生津养血，行滞通痹，托毒排脓，敛疮生肌'::text, '生用或蜜炙（炙黄芪）'::text, '山西、内蒙古、甘肃'::text, '条粗长、皱纹少、质坚而绵、断面黄白色、粉性足、味甜者佳'::text, 'none'::text, '表实邪盛、气滞湿阻、食积停滞、阴虚阳亢、痈疽初起或溃后热毒尚盛者不宜'::text, '置通风干燥处，防潮，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('白术'::text, 'Atractylodis Macrocephalae Rhizoma'::text, '菊科植物白术的干燥根茎'::text, array['苦', '甘']::text[], '温'::text, array['脾', '胃']::text[], '健脾益气，燥湿利水，止汗，安胎'::text, '生用或麸炒、土炒'::text, '浙江于潜（於术）、安徽'::text, '个大、质坚实、断面黄白色、香气浓者佳'::text, 'none'::text, '阴虚燥渴、气滞胀闷者忌用'::text, '置阴凉干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('山药'::text, 'Dioscoreae Rhizoma'::text, '薯蓣科植物薯蓣的干燥根茎'::text, array['甘']::text[], '平'::text, array['脾', '肺', '肾']::text[], '补脾养胃，生津益肺，补肾涩精'::text, '生用或麸炒'::text, '河南焦作一带（怀山药）'::text, '条粗、质坚实、粉性足、色洁白者佳'::text, 'none'::text, '湿盛中满或有实邪、积滞者不宜'::text, '置通风干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('甘草'::text, 'Glycyrrhizae Radix et Rhizoma'::text, '豆科植物甘草、胀果甘草或光果甘草的干燥根和根茎'::text, array['甘']::text[], '平'::text, array['心', '肺', '脾', '胃']::text[], '补脾益气，清热解毒，祛痰止咳，缓急止痛，调和诸药'::text, '生用或蜜炙（炙甘草）'::text, '内蒙古、甘肃、新疆'::text, '皮细紧、色红棕、质坚实、断面黄白色、粉性足、味甜者佳'::text, 'none'::text, '不宜与海藻、京大戟、红大戟、甘遂、芫花同用；湿盛胀满、水肿者不宜；不宜大量久服'::text, '置通风干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('大枣'::text, 'Jujubae Fructus'::text, '鼠李科植物枣的干燥成熟果实'::text, array['甘']::text[], '温'::text, array['脾', '胃', '心']::text[], '补中益气，养血安神'::text, '生用，用时破开或去核'::text, '河北、河南、山东、山西、新疆'::text, '个大、色紫红、肉厚、油润、味甜者佳'::text, 'none'::text, '湿盛中满、食积、齿病及痰热咳嗽者慎用'::text, '置干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('当归'::text, 'Angelicae Sinensis Radix'::text, '伞形科植物当归的干燥根'::text, array['甘', '辛']::text[], '温'::text, array['肝', '心', '脾']::text[], '补血活血，调经止痛，润肠通便'::text, '生用或酒炙（酒当归偏于活血）'::text, '甘肃岷县（岷当归）'::text, '主根粗长、油润、外皮色黄棕、断面色黄白、香气浓郁者佳'::text, 'none'::text, '湿盛中满、大便溏泄者慎用'::text, '置阴凉干燥处，防潮，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('熟地黄'::text, 'Rehmanniae Radix Praeparata'::text, '生地黄的炮制加工品（酒炖或蒸）'::text, array['甘']::text[], '微温'::text, array['肝', '肾']::text[], '补血滋阴，益精填髓'::text, '酒炖或清蒸'::text, '河南焦作一带'::text, '块大、乌黑油亮、质柔软、味甜者佳'::text, 'none'::text, '脾胃虚弱、气滞痰多、脘腹胀痛、食少便溏者忌用'::text, '置通风干燥处'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('白芍'::text, 'Paeoniae Radix Alba'::text, '毛茛科植物芍药的干燥根'::text, array['苦', '酸']::text[], '微寒'::text, array['肝', '脾']::text[], '养血调经，敛阴止汗，柔肝止痛，平抑肝阳'::text, '生用、炒用或酒炙'::text, '浙江（杭白芍）、安徽亳州（亳白芍）、四川（川白芍）'::text, '根粗长、匀直、质坚实、粉性足、表面洁净者佳'::text, 'none'::text, '不宜与藜芦同用；阳衰虚寒者不宜单用'::text, '置干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('阿胶'::text, 'Asini Corii Colla'::text, '马科动物驴的干燥皮或鲜皮经煎煮、浓缩制成的固体胶'::text, array['甘']::text[], '平'::text, array['肺', '肝', '肾']::text[], '补血滋阴，润燥，止血'::text, '烊化兑服；或用蛤粉、蒲黄炒成阿胶珠'::text, '山东东阿'::text, '色乌黑、光亮、透明、无腥臭气、经夏不软者佳'::text, 'none'::text, '脾胃虚弱、消化不良者慎用'::text, '密闭，置阴凉干燥处'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('何首乌'::text, 'Polygoni Multiflori Radix'::text, '蓼科植物何首乌的干燥块根（生首乌）'::text, array['苦', '甘', '涩']::text[], '微温'::text, array['肝', '心', '肾']::text[], '解毒，消痈，截疟，润肠通便'::text, '生用；黑豆汁炖或蒸后为制何首乌（另列）'::text, '河南、湖北、广西、广东、贵州'::text, '个大、质坚实而重、红褐色、断面无裂隙、显粉性者佳'::text, 'none'::text, '有引起肝损伤的报道，不宜长期、大量服用；肝功能不全者慎用；大便溏泄者不宜'::text, '置干燥处，防蛀'::text, '中国药典'::text, '药典性味项是否标毒性没有核实'::text, 'draft'::text, null::text, null::date),
  ('龙眼肉'::text, 'Longan Arillus'::text, '无患子科植物龙眼的假种皮'::text, array['甘']::text[], '温'::text, array['心', '脾']::text[], '补益心脾，养血安神'::text, '生用'::text, '广西、广东、福建'::text, '片大而厚、色黄棕、半透明、甜味浓者佳'::text, 'none'::text, '湿盛中满或有停饮、痰、火者忌用'::text, '置通风干燥处，防潮，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('麦冬'::text, 'Ophiopogonis Radix'::text, '百合科植物麦冬的干燥块根'::text, array['甘', '微苦']::text[], '微寒'::text, array['心', '肺', '胃']::text[], '养阴生津，润肺清心'::text, '通常生用'::text, '浙江（浙麦冬）、四川绵阳（川麦冬）'::text, '粒大饱满、淡黄白色、略透明、质柔韧者佳'::text, 'none'::text, '脾胃虚寒、大便溏泄者慎用'::text, '密封，置阴凉干燥处，防潮，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('天冬'::text, 'Asparagi Radix'::text, '百合科植物天冬的干燥块根'::text, array['甘', '苦']::text[], '寒'::text, array['肺', '肾']::text[], '养阴润燥，清肺生津'::text, '生用'::text, '贵州、四川、广西'::text, '条粗壮、色黄白、半透明者佳'::text, 'none'::text, '脾胃虚寒、食少便溏及外感风寒咳嗽者忌用'::text, '置通风干燥处，防霉，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('南沙参'::text, 'Adenophorae Radix'::text, '桔梗科植物轮叶沙参或沙参的干燥根'::text, array['甘']::text[], '微寒'::text, array['肺', '胃']::text[], '养阴清肺，益胃生津，化痰，益气'::text, '生用'::text, '安徽、江苏、浙江、贵州'::text, '根粗大、饱满、无外皮、色黄白者佳'::text, 'none'::text, '不宜与藜芦同用；风寒咳嗽者不宜'::text, '置通风干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('北沙参'::text, 'Glehniae Radix'::text, '伞形科植物珊瑚菜的干燥根（北沙参）'::text, array['甘', '微苦']::text[], '微寒'::text, array['肺', '胃']::text[], '养阴清肺，益胃生津'::text, '生用'::text, '山东莱阳、河北、辽宁'::text, '条细长、圆柱形、质坚实、色黄白者佳'::text, 'none'::text, '不宜与藜芦同用；风寒咳嗽者不宜'::text, '置通风干燥处，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('玉竹'::text, 'Polygonati Odorati Rhizoma'::text, '百合科植物玉竹的干燥根茎'::text, array['甘']::text[], '微寒'::text, array['肺', '胃']::text[], '养阴润燥，生津止渴'::text, '生用'::text, '湖南、河南、江苏、浙江'::text, '条长、肉肥、黄白色、光泽柔润者佳'::text, 'none'::text, '脾虚有湿痰气滞者不宜'::text, '置通风干燥处，防霉，防蛀'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('百合'::text, 'Lilii Bulbus'::text, '百合科植物卷丹、百合或细叶百合的干燥肉质鳞叶'::text, array['甘']::text[], '寒'::text, array['心', '肺']::text[], '养阴润肺，清心安神'::text, '生用或蜜炙'::text, '湖南、浙江、江苏宜兴、甘肃兰州'::text, '鳞叶均匀、肉厚、质硬、筋少、色白者佳'::text, 'none'::text, '风寒咳嗽及中寒便溏者忌用'::text, '置通风干燥处'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
  ('石斛'::text, 'Dendrobii Caulis'::text, '兰科植物金钗石斛、霍山石斛、鼓槌石斛或流苏石斛的栽培品及其同属植物近似种的新鲜或干燥茎'::text, array['甘']::text[], '微寒'::text, array['胃', '肾']::text[], '益胃生津，滋阴清热'::text, '生用；鲜品清热生津力强'::text, '广西、贵州、云南、安徽霍山'::text, '色金黄、有光泽、质柔韧者佳'::text, 'none'::text, '温热病早期阴未伤者、湿温病未化燥者、脾胃虚寒者忌用'::text, '干品置通风干燥处，防潮；鲜品置阴凉潮湿处，防冻'::text, '中国药典'::text, null::text, 'draft'::text, null::text, null::date),
