-- 每味都要导进去（目录在上面刚补齐，少了说明名字对不上）
do $$
declare missing text;
begin
  select string_agg(n, '、') into missing
  from unnest(array['麻黄', '桂枝', '紫苏叶', '生姜', '荆芥', '防风', '白芷', '薄荷', '桑叶', '菊花', '葛根', '柴胡', '升麻', '石膏', '知母', '栀子', '黄芩', '黄连', '黄柏', '关黄柏', '金银花', '连翘', '蒲公英', '生地黄', '玄参', '牡丹皮', '赤芍', '大黄', '独活', '羌活', '藿香', '广藿香', '苍术', '厚朴', '砂仁', '茯苓', '猪苓', '泽泻', '薏苡仁', '车前子', '干姜', '肉桂', '陈皮', '枳壳', '枳实', '木香', '香附', '佛手', '山楂', '神曲', '麦芽', '鸡内金', '川芎', '丹参', '桃仁', '红花', '牛膝', '川牛膝', '益母草', '三七', '半夏', '桔梗', '川贝母', '浙贝母', '苦杏仁', '酸枣仁', '远志', '龙骨', '牡蛎', '天麻', '钩藤', '人参', '西洋参', '党参', '太子参', '黄芪', '白术', '山药', '甘草', '大枣', '当归', '熟地黄', '白芍', '阿胶', '何首乌', '龙眼肉', '麦冬', '天冬', '南沙参', '北沙参', '玉竹', '百合', '石斛', '铁皮石斛', '枸杞子', '女贞子', '杜仲', '续断', '菟丝子', '淫羊藿', '五味子', '山茱萸', '莲子', '芡实', '浮小麦', '炙黄芪', '炙甘草', '炒白术', '法半夏', '姜半夏', '炒酸枣仁', '焦山楂', '炒麦芽', '炒薏苡仁', '酒当归', '醋香附', '煅龙骨', '煅牡蛎', '制何首乌']::text[]) n
  where not exists (select 1 from public.herb_monographs m join public.herbs h on h.id = m.herb_id where h.name_zh = n);
  if missing is not null then raise exception '这些药没有导入资料：%', missing; end if;
end $$;
